    private static readonly byte[] CompressedArchive = Convert.FromBase64String(ArchiveBase64);
    private static readonly ReadOnlyDictionary<string, ReadOnlyMemory<byte>> Values = ReadArchive();

    internal static IReadOnlyDictionary<string, ReadOnlyMemory<byte>> All => Values;

    internal static ReadOnlySpan<byte> Archive => CompressedArchive;

    internal static ReadOnlyMemory<byte> Read(string key)
        => Values.TryGetValue(key, out var bytes)
            ? bytes
            : throw new InvalidDataException($"Embedded Extension asset '{key}' is missing.");

    private static ReadOnlyDictionary<string, ReadOnlyMemory<byte>> ReadArchive()
    {
        var values = new Dictionary<string, ReadOnlyMemory<byte>>(StringComparer.Ordinal);
        using var compressed = new MemoryStream(CompressedArchive, writable: false);
        using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
        using var reader = new StreamReader(
            gzip,
            new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true),
            detectEncodingFromByteOrderMarks: false);
        while (reader.ReadLine() is { } line)
        {
            var separator = line.IndexOf('\t');
            if (separator <= 0
                || !values.TryAdd(
                    line[..separator],
                    Convert.FromBase64String(line[(separator + 1)..])))
            {
                throw new InvalidDataException("The embedded Extension asset archive is invalid.");
            }
        }

        return new ReadOnlyDictionary<string, ReadOnlyMemory<byte>>(values);
    }
